.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:22px}.eyebrow{font-size:9px;letter-spacing:.18em;color:#54cde8}.hero h1{margin:6px 0;font-size:clamp(28px,3.2vw,44px)}.hero p{margin:0;color:#7898a5;font-size:12px;line-height:1.65;max-width:720px}.back{font-size:10px;color:#9bc0ca;text-decoration:none;white-space:nowrap}.builder-card{border:1px solid var(--line);border-radius:17px;background:linear-gradient(145deg,rgba(8,38,52,.84),rgba(3,21,30,.82));overflow:hidden}.builder-head{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:16px;border-bottom:1px solid var(--line)}.builder-head strong{display:block;color:#e7f8fb;font-size:13px}.builder-head small{display:block;color:#6f8e98;font-size:9px;margin-top:4px}.primary{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:11px;padding:10px 14px;background:linear-gradient(135deg,#25abc9,#1687a4);color:#fff;font-size:10px;font-weight:800;cursor:pointer}.section-row{display:grid;grid-template-columns:26px 40px minmax(0,1fr) 48px;gap:11px;align-items:center;margin:10px;padding:12px;border:1px solid rgba(104,204,235,.12);border-radius:12px;background:rgba(2,15,23,.65);transition:.2s}.section-row.dragging{opacity:.4}.section-row.drop-target{outline:1px dashed #56d2ee}.grip{color:#598592;cursor:grab}.section-icon{width:40px;height:40px;border-radius:11px;display:grid;place-items:center;color:#62d9ee;background:rgba(67,194,229,.08)}.section-copy strong{display:block;font-size:11px;color:#dff4f7}.section-copy small{display:block;font-size:8px;color:#6d8c97;margin-top:4px}.switch{position:relative;width:40px;height:22px;display:block}.switch input{opacity:0;width:0;height:0}.switch span{position:absolute;inset:0;border-radius:99px;background:#18303a;border:1px solid #31505a;cursor:pointer}.switch span:before{content:'';position:absolute;width:16px;height:16px;left:2px;top:2px;border-radius:50%;background:#78939c;transition:.2s}.switch input:checked+span{background:rgba(42,183,213,.22);border-color:rgba(86,210,238,.55)}.switch input:checked+span:before{transform:translateX(18px);background:#69e0f3}@media(max-width:600px){.hero{display:block}.back{display:inline-block;margin-top:12px}.builder-head{align-items:flex-start;flex-direction:column}.section-row{grid-template-columns:22px 36px minmax(0,1fr) 40px}.section-icon{width:36px;height:36px}}
