@push('scripts')<script>
(()=>{const list=document.getElementById('section-list'),fields=document.getElementById('order-fields');if(!list)return;let drag=null;function sync(){fields.innerHTML=[...list.querySelectorAll('.section-row')].map(x=>'<input type="hidden" name="section_order[]" value="'+x.dataset.key+'">').join('')}list.querySelectorAll('.section-row').forEach(row=>{row.addEventListener('dragstart',()=>{drag=row;row.classList.add('dragging')});row.addEventListener('dragover',e=>{e.preventDefault();row.classList.add('drop-target')});row.addEventListener('dragleave',()=>row.classList.remove('drop-target'));row.addEventListener('drop',e=>{e.preventDefault();row.classList.remove('drop-target');if(!drag||drag===row)return;const rect=row.getBoundingClientRect();if(e.clientY<rect.top+rect.height/2)list.insertBefore(drag,row);else list.insertBefore(drag,row.nextSibling);sync()});row.addEventListener('dragend',()=>{row.classList.remove('dragging');drag=null;sync()})});sync()})();
</script>@endpush